insert into public.ml_questionnaires(id,content) values ('pdf-1.1', $q${"fr":{"common":[{"id":"q1","label":"Mission","text":"A-t-il respecté la mission et les consignes de son poste ?"},{"id":"q2","label":"Prise d'information","text":"A-t-il pris des informations avant de recevoir ou d'agir ?"},{"id":"q3","label":"Technique sous pression","text":"A-t-il exécuté ses gestes techniques sous pression ?"},{"id":"q4","label":"Décision","text":"A-t-il choisi la solution adaptée au moment du jeu ?"},{"id":"q5","label":"Transitions","text":"A-t-il réagi après une perte ou une récupération ?"},{"id":"q6","label":"Communication","text":"A-t-il communiqué et gardé sa concentration ?"}],"specific":{"GK":[{"id":"q1","label":"Placement","text":"Son placement a-t-il protégé le but et la profondeur ?"},{"id":"q2","label":"Arrêts","text":"A-t-il réalisé les arrêts attendus et sécurisé les ballons ?"},{"id":"q3","label":"Décision de sortie","text":"A-t-il bien décidé de sortir sur les centres et les ballons en profondeur ?"},{"id":"q4","label":"Relance","text":"Ses relances ont-elles permis de ressortir ou de trouver une cible ?"},{"id":"q5","label":"Commandement","text":"A-t-il guidé sa défense ?"}],"CB":[{"id":"q1","label":"Ligne et profondeur","text":"A-t-il maîtrisé la profondeur et la ligne défensive ?"},{"id":"q2","label":"Duels","text":"A-t-il bien géré ses duels ?"},{"id":"q3","label":"Couverture","text":"A-t-il protégé l'axe et couvert son partenaire ?"},{"id":"q4","label":"Première relance","text":"A-t-il assuré une première passe utile vers l'avant ?"},{"id":"q5","label":"Jeu aérien","text":"A-t-il défendu efficacement les centres et ballons aériens ?"}],"FB":[{"id":"q1","label":"Un contre un","text":"A-t-il contenu son adversaire direct ?"},{"id":"q2","label":"Second poteau","text":"A-t-il protégé le second poteau ?"},{"id":"q3","label":"Projection","text":"A-t-il choisi le bon moment pour monter ?"},{"id":"q4","label":"Dernier geste","text":"Ses centres ou passes en retrait ont-ils créé du danger ?"},{"id":"q5","label":"Repli","text":"A-t-il effectué ses replis défensifs ?"}],"DM":[{"id":"q1","label":"Protection de l'axe","text":"A-t-il protégé l'axe devant la défense ?"},{"id":"q2","label":"Récupération","text":"A-t-il récupéré des ballons et disputé les seconds ballons ?"},{"id":"q3","label":"Orientation","text":"A-t-il orienté le jeu et assuré la première relance ?"},{"id":"q4","label":"Résistance au pressing","text":"A-t-il résisté au pressing ?"},{"id":"q5","label":"Couverture","text":"A-t-il compensé les montées de ses partenaires ?"}],"CM":[{"id":"q1","label":"Volume de jeu","text":"A-t-il participé aux deux phases avec un volume constant ?"},{"id":"q2","label":"Intervalles","text":"A-t-il trouvé des espaces pour recevoir ?"},{"id":"q3","label":"Progression","text":"A-t-il fait progresser le jeu par la passe ou la conduite ?"},{"id":"q4","label":"Projection","text":"A-t-il accompagné les attaques ?"},{"id":"q5","label":"Pressing","text":"A-t-il pressé au bon moment ?"}],"AM":[{"id":"q1","label":"Espaces entre les lignes","text":"A-t-il trouvé des espaces entre les lignes ?"},{"id":"q2","label":"Jeu sous pression","text":"A-t-il pu se retourner ou jouer juste sous pression ?"},{"id":"q3","label":"Dernière passe","text":"A-t-il créé des occasions par ses dernières passes ?"},{"id":"q4","label":"Liaison","text":"A-t-il relié efficacement le milieu et l'attaque ?"},{"id":"q5","label":"Pressing haut","text":"A-t-il aidé l'équipe à récupérer haut ?"}],"WG":[{"id":"q1","label":"Un contre un","text":"A-t-il créé un avantage en un contre un ?"},{"id":"q2","label":"Appels","text":"Ses appels ont-ils donné de la profondeur ?"},{"id":"q3","label":"Création","text":"A-t-il créé des occasions par ses centres ou conduites ?"},{"id":"q4","label":"Choix offensif","text":"A-t-il bien choisi entre dribbler, passer, centrer et tirer ?"},{"id":"q5","label":"Repli","text":"A-t-il participé au repli défensif ?"}],"ST":[{"id":"q1","label":"Appels","text":"A-t-il proposé des appels utiles et attaqué les espaces ?"},{"id":"q2","label":"Jeu en appui","text":"A-t-il conservé le ballon et combiné avec ses partenaires ?"},{"id":"q3","label":"Finition","text":"A-t-il bien choisi ses gestes de finition ?"},{"id":"q4","label":"Présence dans la surface","text":"A-t-il occupé les bonnes zones dans la surface ?"},{"id":"q5","label":"Pressing","text":"A-t-il orienté le pressing adverse ?"}]},"collective":[{"id":"q1","label":"Intensité","text":"L'équipe a-t-elle maintenu son intensité jusqu'au terme ?"},{"id":"q2","label":"Organisation défensive","text":"Le bloc a-t-il protégé les zones clés ?"},{"id":"q3","label":"Transitions","text":"L'équipe a-t-elle réagi après perte et récupération ?"},{"id":"q4","label":"Finition","text":"A-t-elle créé et bien conclu ses occasions ?"},{"id":"q5","label":"Solidité défensive","text":"A-t-elle limité les occasions dangereuses ?"}]}}$q$::jsonb);
alter table public.ml_evaluations add foreign key(questionnaire_version) references public.ml_questionnaires(id);
